package com.portfolio.ecommerce;
import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductRepository repo;public ProductController(ProductRepository repo){this.repo=repo;}@GetMapping public List<Product> all(){return repo.findAll();}@GetMapping("/{id}") public Product get(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Product create(@RequestBody Product p){if(p.getName()==null||p.getName().isBlank()||p.getPrice()==null||p.getPrice().signum()<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"name and positive price required");return repo.save(p);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);repo.deleteById(id);}}